function portalReviewReadiness(result){var plan=result.decision_support||{},brief=plan.brief||{},missing=plan.missing_topics||[],coverage=result.coverage||{},percent=plan.fit_percent==null?coverage.fit_percent:plan.fit_percent;return '<div class="review-readiness"><div class="readiness-fit"><span class="caption">Katalog uyumu</span><strong>'+(percent==null?'—':'%'+fitNumber(percent))+'</strong></div><div><span class="eyebrow">GÖSTERİLEN YZ DEĞERLENDİRMESİ</span><strong>'+esc(plan.action_label||'Kapsam incelemesi gerekiyor')+'</strong><p>'+esc(brief.existing_course&&brief.existing_course.course_name||coverage.reason||'Uygun ders veya çözüm kapsamı değerlendirilecek.')+'</p><span class="readiness-gaps">'+esc(missing.length?missing.length+' eksik kazanım: '+missing.slice(0,3).join(' · ')+(missing.length>3?'…':''):'Analizde eksik kazanım belirtilmedi.')+'</span></div><a class="link-btn" href="#portalAnalysisDetails" data-portal="inspect-analysis">Analiz kanıtlarını incele</a></div>'}
function portalReviewAlreadyRecorded(result){var role=PORTAL.user&&PORTAL.user.role,decision=(result.decisions||[]).find(function(item){return (item.reviewer||{}).role===role});var current=((result.analysis_state||{}).latest_completed||{}).id,reference=(decision||{}).analysis_version||{};if(current&&reference.id!==current&&!((result.analysis_state.latest_completed||{}).imported&&reference.legacy))return false;return !!(decision&&(Number(decision.request_version)===Number(result.version)||['REFERRED','ACTION_PLANNED','RESOLVED'].indexOf(result.status)>=0))}
