  $('#appView').innerHTML='<div data-no-translate><nav class="case-breadcrumb" aria-label="Talep gezinme"><button class="link-btn" data-portal="back-to-list">← Talep listesi</button><span>/</span><span>#'+Number(PORTAL.selectedId)+'</span></nav><div id="portalDetailContent">'+portalSkeleton('Talep ve işlem geçmişi yükleniyor')+'</div></div>';
