function portalReviewReport(data){
  var summary=data.summary||{},learning=data.learning||{},repeated=data.repeated_needs||[];
  return '<div class="grid kpis kpis-four portal-stats">'+kpi('İncelenen talepler',summary.reviewed_requests||0,(summary.total_requests||0)+' toplam talep içinden')+kpi('İnsan incelemesi bekliyor',summary.pending_review||0,'Henüz değerlendirilmemiş talepler')+kpi('Öneriye katılım',summary.agreement_percent==null?'—':'%'+fitPoint(summary.agreement_percent),'Son insan kararının onay olduğu talepler')+kpi('Karar kayıtları',summary.decisions_total||0,'Düzeltmeler dahil tüm değerlendirmeler')+'</div><section class="card learning-summary"><div class="section-title"><div><div class="eyebrow">KARARLARDAN ÖĞRENME</div><h2>İnsan geri bildiriminin etkisi</h2></div><span class="badge b-blue">İnsan kontrolü aktif</span></div><p>'+esc(learning.explanation||'Doğrulanan insan kararları benzer taleplerin değerlendirilmesine katkı sağlar.')+'</p><div class="review-outcome-stats">'+[['APPROVED','Onaylandı',summary.approved],['MODIFIED','Düzeltildi',summary.modified],['REJECTED','Tamamen yanlış',summary.rejected]].map(function(row){return '<div class="decision-'+row[0]+'"><span>'+row[1]+'</span><strong>'+Number(row[2]||0)+'</strong></div>'}).join('')+'</div><p class="caption">Bu sayımlar her talebin son insan kararını gösterir. Katılım oranı, yapay zekânın doğruluk oranı değildir. Bu sürümde model ağırlıkları yeniden eğitilmez ve insan onayı otomatik kaldırılmaz.</p></section>'+(typeof evaluationAggregate==='function'?evaluationAggregate(data.effectiveness):'')+portalRoleReport(data.by_role)+'<section class="card repeated-needs"><div class="section-title"><div><div class="eyebrow">ORTAK GELİŞİM ALANLARI</div><h2>Tekrarlayan ihtiyaçlar</h2></div><span class="caption">'+repeated.length+' konu grubu</span></div><p class="caption">Benzer talep sayısı ile insan tarafından doğrulanmış eğitim ihtiyacı birlikte gösterilir. Çok sayıda başvuru tek başına yeni eğitim kararı değildir.</p>'+(repeated.length?'<div class="report-table-wrap"><table class="report-table"><thead><tr><th scope="col">İhtiyaç konusu</th><th scope="col">Talep</th><th scope="col">Doğrulanan</th><th scope="col">Eksik içerik / kapsam</th><th scope="col">İlgili talepler</th></tr></thead><tbody>'+repeated.map(function(item){return '<tr><th scope="row">'+esc(item.topic)+'</th><td>'+Number(item.request_count)+'</td><td>'+Number(item.confirmed_count)+'</td><td>'+esc((item.missing_topics||[]).join(' · ')||'Eksik başlık kaydı yok')+((item.excess_topics||[]).length?'<span class="caption">Kapsam fazlası: '+item.excess_topics.map(esc).join(' · ')+'</span>':'')+'</td><td>'+portalReportLinks(item.request_ids)+'</td></tr>'}).join('')+'</tbody></table></div>':'<p class="report-empty">Tekrarlayan ihtiyaçlar oluştuğunda burada görünür.</p>')+'</section><div class="scope-report-grid">'+portalScopeReport(data.scope_gaps,'Eksik içerik sinyalleri','Yapay zekâ analizinden ve insan değerlendirmelerinden gelen içerik boşlukları.')+portalScopeReport(data.excess_scope,'Fazla kapsam sinyalleri','İhtiyaç dışı, tekrarlayan veya gereksiz görülen başlıklar.')+'</div>';
}
async function renderReviewReport(){
  var epoch=PORTAL.epoch;
  $('#portalAdminContent').innerHTML=portalSkeleton('Karar ve ihtiyaç raporu hazırlanıyor');
  try{var data=await apiRequest('/api/admin/review-report');if(epoch!==PORTAL.epoch)return;$('#portalAdminContent').innerHTML=portalReviewReport(data)}
  catch(error){if(epoch===PORTAL.epoch)$('#portalAdminContent').innerHTML=portalError(error)+'<button class="btn" data-portal="admin-tab" data-tab="learning">Raporu yeniden yükle</button>'}
}
async function renderAdminSources(){
  var epoch=PORTAL.epoch;
  $('#portalAdminContent').innerHTML='<section class="card"><h2>Bağlantı ve model durumu</h2><div id="aiAvailabilityNotice" class="notice"></div><button class="btn" data-action="retry-ai">Durumu yeniden kontrol et</button><div id="portalModelDetails"></div><div id="documentIndexNotice" class="notice" style="margin-top:20px"></div></section>';
  applyAIStatusToCurrentPage();loadDocumentStatus().catch(portalShowError);
  try{var health=await apiRequest('/api/health',{},35000);if(epoch!==PORTAL.epoch)return;LIVE_AI={status:health.ai_status,message:aiStatusMessage(health),health:health};applyAIStatusToCurrentPage();$('#portalModelDetails').innerHTML='<div class="meta-grid" style="margin-top:20px">'+[['Analiz modeli',health.llm_model],['Arama modeli',health.embedding_model],['Sıralama modeli',health.rerank_model]].map(function(item){return '<div class="meta"><div class="k">'+item[0]+'</div><div class="v">'+esc(item[1])+'</div></div>'}).join('')+'</div><p class="caption">Dosya durumları bu yönetim alanına özeldir. Çalışan yanıtlarında klasör yolları, ham PDF metni ve model ayrıntıları bulunmaz.</p>'}
  catch(error){if(epoch===PORTAL.epoch)$('#portalModelDetails').innerHTML=portalError(error)}
}
async function renderTaxonomyGuide(){
  var epoch=PORTAL.epoch;
  try{var taxonomy=await apiRequest('/api/taxonomy');if(epoch!==PORTAL.epoch)return;$('#portalAdminContent').innerHTML='<div class="notice"><strong>Tek baskın kategori, ayrı ihtiyaç türü.</strong> Konu bir ana/alt gruba yerleşir; eğitim, süreç/araç veya bilgi ihtiyacı ayrıca belirlenir. Belirsiz talepler zorla eşlenmez.</div><div class="taxonomy-grid">'+taxonomy.groups.map(function(group){return '<section class="card"><div class="eyebrow">'+esc(group.id)+'</div><h2>'+esc(group.name)+'</h2><p class="taxonomy-boundary">'+esc(group.boundary)+'</p><ul>'+group.children.map(function(child){return '<li><strong>'+esc(child.name)+'</strong><span>'+esc(child.description)+'</span></li>'}).join('')+'</ul></section>'}).join('')+'</div><p class="caption">Taksonomi sürümü: '+esc(taxonomy.version)+'. Geçmiş kayıtlar otomatik olarak yeniden sınıflandırılmaz.</p>'}catch(error){if(epoch===PORTAL.epoch)$('#portalAdminContent').innerHTML=portalError(error)}
}
document.addEventListener('click',async function(event){
  var button=event.target.closest('[data-portal]');if(!button)return;var action=button.dataset.portal;
  try{
    if(action==='inspect-analysis'){event.preventDefault();var analysisDetails=$('#portalAnalysisDetails');if(analysisDetails){analysisDetails.open=true;analysisDetails.scrollIntoView({block:'start',behavior:'auto'});var summary=analysisDetails.querySelector('summary');if(summary)summary.focus({preventScroll:true})}return}
    if(action==='reload-detail'){render();return}
    if(action==='retry-list'){loadPortalList(button.dataset.admin==='1');return}
    if(action==='home-filter'){PORTAL.filter=button.dataset.status;PORTAL.search='';PORTAL.offset=0;PORTAL.list={};state.currentPage='portal-requests';render();return}
    if(action==='quick-filter'){PORTAL.filter=button.dataset.status;PORTAL.view='';PORTAL.offset=0;var statusField=$('#portalStatus');if(statusField)statusField.value=PORTAL.filter;portalSaveFilters(button.dataset.admin==='1');loadPortalList(button.dataset.admin==='1');return}
    if(action==='reload'){await initPortal();return}
    if(action==='open-request'){openPortalRequest(button.dataset.id,button.dataset.admin==='1');return}
    if(action==='back-to-list'){if(PORTAL.isAdmin){PORTAL.adminTab='requests';state.currentPage='admin-panel'}else state.currentPage='portal-requests';render();return}
    if(action==='list-prev'||action==='list-next'){PORTAL.offset=Math.max(0,PORTAL.offset+(action==='list-next'?20:-20));loadPortalList(button.dataset.admin==='1');return}
    if(action==='admin-tab'){PORTAL.adminTab=button.dataset.tab;PORTAL.offset=0;render();return}
    if(action==='account-logout'){await apiRequest('/api/auth/logout',{method:'POST'});clearPortalAccount();state.currentPage='portal-login';setMobileMenu(false);render();return}
    
  }catch(error){portalShowError(error)}
});

function portalQueueControls(data,admin){var container=$('#portalQueueViews');if(!container)return;container.innerHTML=(data.queue_views||[]).map(function(view){return '<button class="quick-filter '+((PORTAL.view||'')===view.id?'active':'')+'" type="button" data-view="'+esc(view.id)+'" aria-pressed="'+((PORTAL.view||'')===view.id)+'">'+esc(view.label)+'</button>'}).join('');container.querySelectorAll('button').forEach(function(button){button.addEventListener('click',function(){PORTAL.view=button.dataset.view;PORTAL.filter='';PORTAL.offset=0;var field=$('#portalStatus');if(field)field.value='';portalSaveFilters(admin);loadPortalList(admin)})})}


function portalAnalysisState(result){
  var state=result.analysis_state;if(!state)return '';var latest=state.latest_run,completed=state.latest_completed;
  var status=latest?latest.status_label:state.legacy_result?'Önceki kayıtlı analiz':'Analiz sürümü bulunmuyor';
  var info=latest&&latest.error_message?'Talebiniz kaydedildi ancak analiz şu anda tamamlanamadı. '+latest.error_message:latest&&['PENDING','PROCESSING'].includes(latest.status)?'Talebiniz kalıcı olarak kayıtlı. Analiz tamamlandığında bu alan güncellenecek.':'';
  return '<section class="card" aria-labelledby="analysisStateTitle"><div class="section-title"><h2 id="analysisStateTitle">'+esc(status)+'</h2>'+(latest?'<span class="caption">Analiz sürümü '+Number(latest.sequence)+'</span>':'')+'</div>'+(info?'<p role="status">'+esc(info)+'</p>':'')+(completed?'<p class="caption">Gösterilen son başarılı analiz: v'+Number(completed.sequence)+' · '+(completed.completed_at?portalDateTime(completed.completed_at):'Tamamlanma zamanı eski kayıtta mevcut değil')+(latest&&latest.id!==completed.id?' · Önceki başarılı sonuç korunuyor.':'')+'</p>':'')+(state.result_is_current_input===false&&completed?'<p class="caption">Güncel talep girdisinin analizi henüz doğrulanmadı; önceki sonuç yeni ek bilgilerin değerlendirmesi sayılmaz.</p>':'')+'<div id="portalAnalysisError" role="alert"></div>'+(state.available_actions||[]).map(function(action){return '<button class="btn" type="button" data-analysis-action="'+esc(action.code)+'">'+esc(action.label)+'</button>'}).join('')+'</section>';
}
function bindPortalAnalysis(result,epoch,admin){
  var state=result.analysis_state;if(!state)return;
  document.querySelectorAll('[data-analysis-action]').forEach(function(button){var busy=false,key=crypto.randomUUID();button.addEventListener('click',async function(){if(busy)return;busy=true;button.disabled=true;try{await apiRequest((admin?'/api/admin/requests/':'/api/requests/')+result.request_id+'/analysis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_version:result.version,idempotency_key:key})});if(epoch===PORTAL.epoch)render()}catch(error){if(epoch===PORTAL.epoch)$('#portalAnalysisError').innerHTML=portalError(error)+(error.status===409?'<button class="btn" type="button" data-portal="reload-detail">Güncel kaydı aç</button>':'')}finally{busy=false;button.disabled=false}})});
  if(state.latest_run&&['PENDING','PROCESSING'].includes(state.latest_run.status)){
    var poll=async function(){if(epoch!==PORTAL.epoch||!PORTAL.user)return;try{var fresh=await apiRequest((admin?'/api/admin/requests/':'/api/requests/')+result.request_id);if(epoch!==PORTAL.epoch)return;var run=(fresh.analysis_state||{}).latest_run;if(!run||run.status!==state.latest_run.status||fresh.version!==result.version){render();return}}catch(error){if(epoch!==PORTAL.epoch)return;var errorNode=$('#portalAnalysisError');if(errorNode)errorNode.innerHTML=portalError(error)+'<button class="btn" type="button" data-portal="reload-detail">Kaydı yeniden yükle</button>';return}setTimeout(poll,2500)};setTimeout(poll,2500);
  }
}
